/* Admin console */
(function () {
  const RC = window.RC, D = RC.DATA, I = RC.ico, $ = RC.$, S = () => RC.S;
  const view = (active, title, sub, actions, inner, mount) => ({ html: RC.shell('admin', active, title, sub, actions, inner), mount: a => { RC.shellMount('admin'); mount && mount(a); } });
  const audit = t => { S().auditLive = S().auditLive || []; S().auditLive.unshift(['Sneha Kulkarni', t, 'Just now']); RC.save(); };
  const notifyStudent = (t, kind) => { S().notifications.unshift({ id: RC.uid(), text: t, kind: kind || 'good', t: 'Just now', read: false }); };
  const CR = .10, RQ = .0610, RL = .0387;
  const completes = c => { if (c < 90) return Math.floor(c / 20) + ' tailored resume(s) — not enough for a mock interview'; if (c < 110) return '1 mock interview, or ' + Math.floor(c / 20) + ' tailored resumes'; if (c < 200) return 'Job Hunt & Resume Kit' + (c >= 140 ? ' + apply pack' : ''); if (c < 340) return 'Interview Kit, or Job Hunt + Apply Kit'; const k = Math.floor(c / 340), rem = c % 340; return k + ' full Job-Ready Kit' + (k > 1 ? 's' : '') + (rem ? ' + ' + rem + ' spare' : ''); };
  const mtdSpend = () => D.costs.spend.slice(-20).reduce((a, b) => a + b, 0);
  const days30 = () => Array.from({ length: 30 }, (_, i) => { const d = RC.daysAgo(29 - i); return d.getDate() + ''; });
  const GROUPS = [['AWS DevOps · Sept 2026', 24], ['Azure Admin · Aug 2026', 18], ['Python & Data · Sept 2026', 20], ['Cyber Security · Aug 2026', 12], ['Public sign-up', 96]];
  const statusBadge = s => `<span class="badge ${s === 'active' ? 'green' : s === 'blocked' ? 'red' : 'amber'}">${s}</span>`;

  /* ============================================================ DASHBOARD */
  RC.route('/a/dashboard', 'admin', () => {
    const pend = S().requests.filter(r => r.status === 'pending'), pp = S().planRequests.filter(r => ['requested', 'paid'].includes(r.status)), spend = mtdSpend(), pct = Math.round(spend / D.costs.cap * 100);
    return view('dashboard', 'Good morning, Sneha', 'Radical CareerAI · ' + RC.fmtDate(RC.today) + ' · Placement dashboard', `<button class="btn" id="exp">${I('download', 16)} Export report</button><a class="btn primary" href="#/a/requests">${I('clip', 16)} Review requests (${pend.length + pp.length})</a>`, `
      <div class="callout warn mb16">${I('alert', 18)}<div><b>AI spend is at ${pct}% of the monthly cap</b> (${RC.inr(spend)} of ${RC.inr(D.costs.cap)}). Switching the interview scorecards to <b>Lean</b> mode would save about 60% on those sessions. <a href="#/a/costs" class="bold">Open cost monitor</a></div></div>
      <div class="g4"><div class="card kpi-card"><div class="kpi"><span class="l">Registered students</span><span class="v">1,240</span><span class="d up">▲ 86 this week</span></div><div class="ic" style="background:var(--red-l);color:var(--red)">${I('users')}</div></div>
        <div class="card kpi-card"><div class="kpi"><span class="l">Active this month</span><span class="v">434</span><span class="d up">35% of registered</span></div><div class="ic" style="background:var(--green-l);color:var(--green)">${I('activity')}</div></div>
        <div class="card kpi-card"><div class="kpi"><span class="l">AI spend (month to date)</span><span class="v">${RC.inr(spend)}</span><span class="d ${pct > 75 ? 'down' : 'up'}">${pct}% of ₹${RC.num(D.costs.cap)} cap</span></div><div class="ic" style="background:var(--amber-l);color:var(--amber)">${I('rupee')}</div></div>
        <div class="card kpi-card"><div class="kpi"><span class="l">Cost per active student</span><span class="v">${RC.inr(spend / 434)}</span><span class="d up">▼ 12% vs last month</span></div><div class="ic" style="background:var(--violet-l);color:var(--violet)">${I('trend')}</div></div></div>
      <div class="g-main mt16"><div class="col gap18"><div class="card"><div class="card-h"><h3>Daily AI spend — last 30 days</h3><span class="badge steel">₹ per day</span></div>${RC.lineChart(days30(), [{ name: 'AI spend', color: '#B3282D', data: D.costs.spend }], { h: 220, legend: false, fmt: v => '₹' + Math.round(v) })}</div>
        <div class="g2"><div class="card"><div class="card-h"><h3>Student funnel</h3></div>${D.funnel.slice(0, 6).map((f, i) => `<div class="row gap8 mb8"><span class="small" style="width:150px">${f[0]}</span><div class="progress grow"><i style="width:${f[1] / 12.4}%;${i > 3 ? 'background:var(--green)' : ''}"></i></div><b class="mono small" style="width:46px;text-align:right">${RC.num(f[1])}</b></div>`).join('')}</div>
        <div class="card"><div class="card-h"><h3>Top skill gaps</h3><a class="small bold" href="#/a/reports">More</a></div>${D.gaps.slice(0, 5).map(g => `<div class="row gap8 mb8"><span class="small" style="width:150px">${g[0]}</span><div class="progress r grow thin"><i style="width:${g[1] * 2}%"></i></div><b class="mono small">${g[1]}%</b></div>`).join('')}<div class="small muted mt8">% of students scoring below 50 — used to plan Radical batches.</div></div></div></div>
      <div class="col gap18"><div class="card"><div class="card-h"><h3>${I('clip', 18)} Needs your approval</h3><span class="badge red">${pend.length + pp.length}</span></div>${pend.slice(0, 3).map(r => `<div class="row gap8 mb12">${RC.av(r.av, 36)}<div class="grow"><b class="small">${r.student}</b><div class="tiny muted">wants ${r.ask} credits</div></div><a class="btn sm" href="#/a/requests">Review</a></div>`).join('')}${pp.map(r => `<div class="row gap8 mb12">${RC.av(r.av, 36)}<div class="grow"><b class="small">${r.student}</b><div class="tiny muted">Premium plan · ${r.status === 'paid' ? 'payment submitted' : 'needs a quote'}</div></div><a class="btn sm ${r.status === 'paid' ? 'green' : ''}" href="#/a/requests?t=plans">${r.status === 'paid' ? 'Confirm' : 'Quote'}</a></div>`).join('')}</div>
        <div class="card"><div class="card-h"><h3>AI spend by feature</h3></div>${RC.donut(D.costs.byFeature.map(f => ({ n: f.n, v: f.v, c: f.c, f: RC.inr(f.v / 10190 * spend) })), 130, RC.inr(spend), 'MTD')}</div>
        <div class="card"><div class="card-h"><h3>Recent activity</h3></div><div class="timeline">${(S().auditLive || []).concat(D.audit).slice(0, 5).map(a => `<div class="ev"><div class="small">${a[1]}</div><div class="tiny muted">${a[0]} · ${a[2]}</div></div>`).join('')}</div></div></div></div>`, a => { $('#exp', a).onclick = () => RC.toast('Report exported: <b>careerai-dashboard-Sep-2026.xlsx</b> (demo)', 'info'); });
  });

  /* ============================================================ USERS */
  const userDrawer = u => {
    const isA = u.id === 'u_aarav', ov = S().userOverrides[u.id] = S().userOverrides[u.id] || {}; const mods = [['jobs', 'Job matches'], ['resume', 'Resume Studio'], ['cover', 'Cover letters'], ['tracker', 'Applications'], ['interview', 'Interview Lab'], ['learn', 'Radical courses']];
    const val = k => isA ? S().modules[k] !== false : ov[k] !== false; const plan = isA ? S().plan : (ov.plan || u.plan); const bal = isA ? RC.balance() : (ov.credits != null ? ov.credits : u.credits);
    RC.drawer(`<div class="row gap14 mb16">${RC.av(u.av, 64)}<div><h2>${u.name}</h2><div class="muted small">${u.email}</div><div class="row gap6 mt8">${statusBadge(ov.status || u.status)}<span class="badge ${u.type === 'radical' ? 'red' : ''}">${u.type === 'radical' ? 'Radical student' : 'Public user'}</span><span class="badge ${plan === 'premium' ? 'violet' : ''}">${plan}</span></div></div></div>
      <div class="g2 mb16"><div class="card flat tight kpi"><span class="l">Credits</span><span class="v">${bal}</span></div><div class="card flat tight kpi"><span class="l">Avg mock score</span><span class="v">${u.mock}</span></div><div class="card flat tight kpi"><span class="l">Applications</span><span class="v">${u.apps}</span></div><div class="card flat tight kpi"><span class="l">Last active</span><span class="v" style="font-size:18px">${u.last === 0 ? 'Today' : u.last + ' d ago'}</span></div></div>
      <dl class="kv mb16"><dt>City</dt><dd>${u.city}</dd><dt>Batch</dt><dd>${u.batch}</dd><dt>Joined</dt><dd>${RC.fmtDate(RC.daysAgo(u.joined))}</dd></dl>
      <h4 class="mb8">Module access for this student</h4><div class="card flat">${mods.map(m => `<div class="row between" style="padding:8px 0;border-bottom:1px solid var(--line2)"><span>${m[1]}</span><div class="switch ${val(m[0]) ? 'on' : ''}" data-m="${m[0]}"></div></div>`).join('')}</div>
      <div class="row gap8 mt16"><button class="btn primary grow" id="dGrant">${I('plus', 14)} Grant credits</button><select class="input" id="dPlan" style="width:130px"><option value="basic" ${plan === 'basic' ? 'selected' : ''}>Basic</option><option value="premium" ${plan === 'premium' ? 'selected' : ''}>Premium</option></select><button class="btn" id="dBlock" style="color:var(--red)">${(ov.status || u.status) === 'blocked' ? 'Unblock' : 'Block'}</button></div>`, d => {
      RC.$$('[data-m]', d).forEach(sw => sw.onclick = () => { sw.classList.toggle('on'); const on = sw.classList.contains('on'); if (isA) S().modules[sw.dataset.m] = on; else ov[sw.dataset.m] = on; audit((on ? 'Enabled ' : 'Disabled ') + sw.parentElement.firstElementChild.textContent + ' for ' + u.name); RC.save(); RC.toast((on ? 'Enabled' : 'Disabled') + ' ' + sw.parentElement.firstElementChild.textContent, 'info'); });
      $('#dGrant', d).onclick = () => { RC.closeDrawer(); grantModal(u); }; $('#dPlan', d).onchange = e => { if (isA) { S().plan = e.target.value; if (S().plan === 'premium' && !S().premiumUntil) S().premiumUntil = new Date(2026, 9, 20).toISOString(); } else ov.plan = e.target.value; audit('Changed ' + u.name + '’s interview plan to ' + e.target.value); RC.save(); RC.toast('Plan updated to ' + e.target.value); };
      $('#dBlock', d).onclick = () => { ov.status = (ov.status || u.status) === 'blocked' ? 'active' : 'blocked'; audit((ov.status === 'blocked' ? 'Blocked ' : 'Unblocked ') + u.name); RC.save(); RC.closeDrawer(); RC.toast(u.name + ' ' + ov.status); RC.render(); };
    });
  };
  RC.route('/a/users', 'admin', () => {
    return view('users', 'Users & enrolment', '1,240 registered · 312 Radical students · 928 public sign-ups', `<button class="btn" id="imp">${I('upload', 16)} Import students (CSV)</button><button class="btn primary" id="addU">${I('plus', 16)} Add student</button>`, `
      <div class="card tight mb16"><div class="filters"><div class="search" style="max-width:280px;flex:none">${I('search', 16)}<input id="uq" placeholder="Search name, email, batch" value="${RC.esc(S().q || '')}"></div><select class="input" id="uT" style="width:150px"><option value="">All users</option><option value="radical">Radical students</option><option value="public">Public users</option></select><select class="input" id="uB" style="width:200px"><option value="">All batches</option>${GROUPS.map(g => `<option>${g[0]}</option>`).join('')}</select><select class="input" id="uS" style="width:130px"><option value="">Any status</option><option>active</option><option>pending</option><option>blocked</option></select><span class="muted small" id="uC"></span></div></div>
      <div class="card pad0" style="overflow:auto"><table class="table"><thead><tr><th>Student</th><th>Type</th><th>Batch</th><th>City</th><th>Plan</th><th class="right">Credits</th><th class="right">Mock avg</th><th>Last active</th><th>Status</th></tr></thead><tbody id="uBody"></tbody></table></div>`, a => {
      const draw = () => { const q = $('#uq', a).value.toLowerCase(), t = $('#uT', a).value, b = $('#uB', a).value, st = $('#uS', a).value; const l = D.users.filter(u => { const ov = S().userOverrides[u.id] || {}; return (!q || (u.name + u.email + u.batch).toLowerCase().includes(q)) && (!t || u.type === t) && (!b || u.batch === b) && (!st || (ov.status || u.status) === st); }); $('#uC', a).textContent = l.length + ' shown'; $('#uBody', a).innerHTML = l.map(u => { const ov = S().userOverrides[u.id] || {}; const cr = u.id === 'u_aarav' ? RC.balance() : (ov.credits != null ? ov.credits : u.credits); const plan = u.id === 'u_aarav' ? S().plan : (ov.plan || u.plan); return `<tr class="click" data-u="${u.id}"><td><div class="row gap8">${RC.av(u.av, 34)}<div><b>${u.name}</b><div class="tiny muted">${u.email}</div></div></div></td><td>${u.type === 'radical' ? '<span class="badge red">Radical</span>' : '<span class="badge">Public</span>'}</td><td class="small">${u.batch}</td><td>${u.city}</td><td><span class="badge ${plan === 'premium' ? 'violet' : ''}">${plan}</span></td><td class="right mono ${cr < 50 ? 'down bold' : ''}">${cr}</td><td class="right mono">${u.mock}</td><td class="small muted">${u.last === 0 ? 'Today' : u.last + ' d ago'}</td><td>${statusBadge(ov.status || u.status)}</td></tr>`; }).join(''); RC.$$('[data-u]', a).forEach(r => r.onclick = () => userDrawer(D.users.find(u => u.id === r.dataset.u))); };
      ['uq', 'uT', 'uB', 'uS'].forEach(id => $('#' + id, a).addEventListener('input', draw)); draw();
      $('#imp', a).onclick = () => RC.modal({ title: 'Import students from CSV', sub: 'Columns: name, email, mobile, city, batch', size: 'wide', body: `<div class="dropzone" id="csvDz">${I('upload', 30)}<h3 class="mt8">Drop CSV here or click</h3><button class="btn dark mt8" id="csvSample">Use sample: aws-devops-sept-2026.csv (48 rows)</button></div><div id="csvPrev"></div>`, mount: m => { $('#csvSample', m).onclick = async e => { e.stopPropagation(); $('#csvDz', m).style.display = 'none'; $('#csvPrev', m).innerHTML = `<div class="callout good mb8">${I('check', 18)}<div>48 rows parsed · 46 valid · 2 duplicates skipped · batch “AWS DevOps · Sept 2026”</div></div><table class="table"><thead><tr><th>Name</th><th>Email</th><th>City</th><th>Batch</th></tr></thead><tbody>${D.users.slice(1, 6).map(u => `<tr><td>${u.name}</td><td>${u.email}</td><td>${u.city}</td><td>AWS DevOps · Sept 2026</td></tr>`).join('')}<tr><td colspan="4" class="muted center">… 41 more rows</td></tr></tbody></table><div class="row gap8 mt16" style="justify-content:flex-end"><button class="btn" data-close>Cancel</button><button class="btn primary" id="doImp">Import 46 students</button></div>`; $('#doImp', m).onclick = () => { audit('Imported 46 students (AWS DevOps · Sept 2026) and granted Free Starter credits'); RC.closeModal(); RC.toast('<b>46 students</b> imported. Free Starter (400 credits) added and invitation e-mails queued.'); }; }; } });
      $('#addU', a).onclick = () => RC.modal({ title: 'Add student', body: `<div class="g2"><div class="field"><label class="f">Name</label><input class="input" value="Tanmay Kelkar"></div><div class="field"><label class="f">Email</label><input class="input" value="tanmay.k@example.com"></div><div class="field"><label class="f">Batch</label><select class="input">${GROUPS.map(g => `<option>${g[0]}</option>`).join('')}</select></div><div class="field"><label class="f">Free credits</label><input class="input" value="400"></div></div>`, footer: `<button class="btn" data-close>Cancel</button><button class="btn primary" id="okA">Add student</button>`, mount: m => $('#okA', m).onclick = () => { audit('Added student Tanmay Kelkar'); RC.closeModal(); RC.toast('Student added and invited'); } });
    });
  });

  /* ============================================================ MODULE ACCESS */
  RC.route('/a/modules', 'admin', () => {
    const mods = [['jobs', 'Job matches'], ['resume', 'Resume Studio'], ['cover', 'Cover letters'], ['tracker', 'Applications & follow-ups'], ['interview', 'Interview Lab'], ['learn', 'Radical courses']];
    S().moduleMatrix = S().moduleMatrix || {};
    const val = (mk, gi) => gi === 0 ? S().modules[mk] !== false : (S().moduleMatrix[mk + gi] != null ? S().moduleMatrix[mk + gi] : !(gi === 4 && mk === 'interview'));
    return view('modules', 'Module access', 'Decide which features each group of students can use — changes apply instantly', `<button class="btn" id="reset">${I('refresh', 16)} Restore defaults</button>`, `
      <div class="callout info mb16">${I('info', 18)}<div>The first column is <b>Aarav’s batch</b> — flip a switch here and open the Student view: the module disappears from his sidebar immediately.</div></div>
      <div class="card"><div class="mx" style="grid-template-columns:1fr"><div class="r h" style="grid-template-columns:240px repeat(5,1fr)"><span>Module</span>${GROUPS.map(g => `<span class="c center" style="text-align:center;line-height:1.3">${g[0].replace(' · ', '<br>')}<br><span class="muted" style="font-weight:500;text-transform:none;letter-spacing:0">${g[1]} students</span></span>`).join('')}</div>
      ${mods.map(m => `<div class="r" style="grid-template-columns:240px repeat(5,1fr)"><b>${m[1]}</b>${GROUPS.map((g, gi) => `<span class="c"><div class="switch ${val(m[0], gi) ? 'on' : ''}" data-m="${m[0]}" data-g="${gi}"></div></span>`).join('')}</div>`).join('')}</div></div>
      <div class="card mt16"><h4 class="mb8">Interview rounds by plan</h4><div class="g3">${[['Aptitude test', 1, 1], ['Technical test', 1, 1], ['HR round', 1, 1], ['Group discussion', 0, 1], ['Coding round', 0, 1], ['Salary negotiation', 0, 1]].map(r => `<div class="row between card flat tight"><b class="small">${r[0]}</b><span class="row gap6"><span class="badge ${r[1] ? 'green' : ''}">Basic ${r[1] ? '✓' : '—'}</span><span class="badge violet">Premium ✓</span></span></div>`).join('')}</div></div>`, a => {
      RC.$$('.switch[data-m]', a).forEach(sw => sw.onclick = () => { const on = !sw.classList.contains('on'); sw.classList.toggle('on', on); const gi = +sw.dataset.g, mk = sw.dataset.m; if (gi === 0) S().modules[mk] = on; else S().moduleMatrix[mk + gi] = on; audit((on ? 'Enabled ' : 'Disabled ') + sw.closest('.r').firstElementChild.textContent + ' for batch ' + GROUPS[gi][0]); RC.save(); RC.toast((on ? 'Enabled' : 'Disabled') + ' <b>' + sw.closest('.r').firstElementChild.textContent + '</b> for ' + GROUPS[gi][0], 'info'); });
      $('#reset', a).onclick = () => { Object.keys(S().modules).forEach(k => S().modules[k] = true); S().moduleMatrix = {}; RC.save(); RC.toast('Defaults restored'); RC.render(); };
    });
  });

  /* ============================================================ CREDITS + GRANT ADVISOR */
  const TARGETS = [['aarav', 'Aarav Sharma (student)', 1], ['b0', 'Batch: AWS DevOps · Sept 2026', 24], ['b1', 'Batch: Azure Admin · Aug 2026', 18], ['b4', 'Batch: Public sign-up', 96], ['all', 'All Radical students', 312]];
  const grantModal = u => {
    RC.modal({
      title: 'Grant credits', sub: 'Grant Advisor shows the cost to Radical before you confirm', size: 'wide', body: `<div class="g2"><div><div class="field"><label class="f">Grant to</label><select class="input" id="gT">${TARGETS.map(t => `<option value="${t[0]}" ${u && u.id === 'u_aarav' && t[0] === 'aarav' ? 'selected' : ''}>${t[1]}</option>`).join('')}</select></div><div class="g2"><div class="field"><label class="f">Free credits</label><input class="input" type="number" id="gF" value="500" min="0"></div><div class="field"><label class="f">Paid credits</label><input class="input" type="number" id="gP" value="500" min="0"></div></div><div class="field"><label class="f">Expiry</label><select class="input"><option>90 days</option><option>30 days</option><option>180 days</option><option>No expiry (paid)</option></select></div><div class="field"><label class="f">Note to student (optional)</label><input class="input" value="Good luck with your placements!"></div></div>
      <div class="card flat" style="background:var(--bg)" id="adv"></div></div>`, footer: `<button class="btn" data-close>Cancel</button><button class="btn primary" id="gGo">Grant credits</button>`, mount: m => {
        const calc = () => { const f = +$('#gF', m).value || 0, p = +$('#gP', m).value || 0, c = f + p, n = TARGETS.find(t => t[0] === $('#gT', m).value)[2]; const w = c < 25 ? ['bad', 'alert', 'Too small: cannot finish even one resume + cover letter'] : c < 110 ? ['warn', 'alert', 'Cannot complete the Job Hunt & Resume Kit (needs 110)'] : ['good', 'check', 'Large enough to finish at least one complete feature set'];
          $('#adv', m).innerHTML = `<div class="row gap8 mb8"><b style="font-family:var(--f-head)">${I('cpu', 16)} Grant Advisor</b></div><div class="kv"><dt>Per student</dt><dd>${c} credits</dd><dt>Students</dt><dd>${n}</dd><dt>Maximum cost</dt><dd style="color:var(--red)">${RC.inr(c * CR * n)}</dd><dt>Expected — Quality AI</dt><dd>${RC.inr(c * RQ * n)}</dd><dt>Expected — Lean AI</dt><dd>${RC.inr(c * RL * n)}</dd></div><div class="divider"></div><div class="small mb8"><b>Each student can complete:</b><br>${completes(c)}</div><div class="callout ${w[0]}" style="font-size:12.5px">${I(w[1], 16)}<div>${w[2]}</div></div>`; };
        ['gF', 'gP', 'gT'].forEach(id => $('#' + id, m).addEventListener('input', calc)); calc();
        $('#gGo', m).onclick = () => { const f = +$('#gF', m).value || 0, p = +$('#gP', m).value || 0, t = $('#gT', m).value, n = TARGETS.find(x => x[0] === t)[2]; if (f + p <= 0) return RC.toast('Enter credits to grant', 'info'); if (['aarav', 'b0', 'all'].includes(t)) { S().wallet.free += f; S().wallet.paid += p; RC.ledgerAdd('Admin grant — ' + (f ? f + ' free' : '') + (f && p ? ' + ' : '') + (p ? p + ' paid' : ''), f + p, 'grant'); notifyStudent('Radical admin granted you <b>' + (f + p) + ' credits</b>.'); } audit('Granted ' + f + ' free + ' + p + ' paid credits to ' + TARGETS.find(x => x[0] === t)[1] + ' (max ' + RC.inr((f + p) * CR * n) + ')'); RC.save(); RC.closeModal(); RC.toast('<b>' + (f + p) + ' credits</b> granted to ' + n + ' student' + (n > 1 ? 's' : '')); if (location.hash.includes('credits')) RC.render(); };
      }
    });
  };
  RC.route('/a/credits', 'admin', () => {
    const top = D.users.slice().sort((a, b) => b.credits - a.credits).slice(0, 6);
    return view('credits', 'Credit wallets', 'Issue free and paid credits — always with the cost in front of you', `<button class="btn primary" id="grant">${I('plus', 16)} Grant credits</button>`, `
      <div class="g4"><div class="card kpi"><span class="l">Credits issued this month</span><span class="v">2,84,500</span><span class="d muted">max cost ${RC.inr(284500 * CR)}</span></div><div class="card kpi"><span class="l">Credits used</span><span class="v">1,12,300</span><span class="d up">39% utilisation</span></div><div class="card kpi"><span class="l">Real AI cost of credits used</span><span class="v">${RC.inr(112300 * RQ)}</span><span class="d muted">≈ ₹0.061 per credit</span></div><div class="card kpi"><span class="l">Expiring in 7 days</span><span class="v">18,400</span><span class="d down">62 students</span></div></div>
      <div class="g-main mt16"><div class="card"><div class="card-h"><h3>Admin cost table</h3><span class="muted small">“If I give this many credits per student, what do I pay?”</span></div><table class="table"><thead><tr><th class="right">Credits / student</th><th class="right">Max ₹</th><th class="right">Expected (Quality)</th><th class="right">Expected (Lean)</th><th>Completes</th></tr></thead><tbody>${[100, 200, 340, 400, 500, 750, 1000, 1500, 3000].map(c => `<tr><td class="right mono bold">${RC.num(c)}</td><td class="right mono">${RC.inr(c * CR)}</td><td class="right mono">${RC.inr(c * RQ, 1)}</td><td class="right mono">${RC.inr(c * RL, 1)}</td><td class="small">${completes(c)}</td></tr>`).join('')}</tbody></table></div>
      <div class="col gap14"><div class="card"><h4 class="mb8">Default credit policy</h4><div class="kv"><dt>Free Starter (once)</dt><dd>400 credits</dd><dt>Radical student monthly top-up</dt><dd>300 credits</dd><dt>Free credit expiry</dt><dd>90 days</dd><dt>Paid credit expiry</dt><dd>12 months</dd><dt>Minimum grant (safety)</dt><dd>110 credits</dd></div><button class="btn block mt12" id="pol">Edit policy</button></div><div class="card"><h4 class="mb8">Highest balances</h4>${top.map(u => `<div class="row gap8 mb8">${RC.av(u.av, 30)}<span class="grow small">${u.name}</span><b class="mono small">${u.id === 'u_aarav' ? RC.balance() : u.credits}</b></div>`).join('')}</div></div></div>`, a => { $('#grant', a).onclick = () => grantModal(); $('#pol', a).onclick = () => RC.toast('Policy editor (demo)', 'info'); });
  });

  /* ============================================================ REQUESTS */
  const approveModal = r => RC.modal({
    title: 'Approve credit request', sub: r.student + ' asked for ' + r.ask + ' credits', body: `<div class="fb-said mb16">“${RC.esc(r.reason)}”</div><div class="g2"><div class="field"><label class="f">Credits to grant</label><input class="input" type="number" id="aAmt" value="${r.ask}"></div><div class="field"><label class="f">Credit type</label><select class="input" id="aTyp"><option>Free</option><option>Paid</option></select></div></div><div class="callout info" id="aCost" style="font-size:12.5px"></div><div class="field mt12"><label class="f">Message to student</label><input class="input" id="aMsg" value="Approved — good luck with the interviews!"></div>`,
    footer: `<button class="btn" data-close>Cancel</button><button class="btn green" id="aGo">${I('check', 16)} Approve</button>`, mount: m => { const c = () => { const n = +$('#aAmt', m).value || 0; $('#aCost', m).innerHTML = `${I('rupee', 16)}<div>Max cost to Radical <b>${RC.inr(n * CR)}</b> · expected <b>${RC.inr(n * RQ, 1)}</b> · completes ${completes(n)}</div>`; }; $('#aAmt', m).oninput = c; c();
      $('#aGo', m).onclick = () => { const n = +$('#aAmt', m).value || 0; r.status = n < r.ask ? 'approved' : 'approved'; r.granted = n; r.note = $('#aMsg', m).value; if (r.mine || r.student === 'Aarav Sharma') { if ($('#aTyp', m).value === 'Free') S().wallet.free += n; else S().wallet.paid += n; RC.ledgerAdd('Admin approved request — ' + n + ' ' + $('#aTyp', m).value.toLowerCase() + ' credits', n, 'grant'); notifyStudent('Radical approved your request: <b>+' + n + ' credits</b>.'); } audit('Approved ' + n + ' credits for ' + r.student); RC.save(); RC.closeModal(); RC.toast('Approved <b>' + n + ' credits</b> for ' + r.student); RC.render(); }; }
  });
  const nextCode = () => 'RC-' + RC.rnd(10000, 99999);
  RC.route('/a/requests', 'admin', () => {
    const q = new URLSearchParams((location.hash.split('?')[1]) || ''); const tab = q.get('t') || 'credits';
    const cr = S().requests, pl = S().planRequests; const pc = cr.filter(r => r.status === 'pending').length, pp = pl.filter(r => ['requested', 'paid'].includes(r.status)).length;
    const credits = `<div class="card pad0"><table class="table"><thead><tr><th>Student</th><th>Request</th><th>Reason</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody>${cr.map(r => `<tr><td><div class="row gap8">${RC.av(r.av, 34)}<b>${r.student}</b></div></td><td class="mono bold">${r.ask}</td><td class="small" style="max-width:340px">${RC.esc(r.reason)}</td><td class="small muted">${RC.fmtDate(r.date)}</td><td>${r.status === 'pending' ? '<span class="badge amber">Pending</span>' : r.status === 'approved' ? `<span class="badge green">Approved +${r.granted}</span>` : '<span class="badge red">Declined</span>'}</td><td class="right">${r.status === 'pending' ? `<button class="btn sm green" data-ap="${r.id}">Approve</button> <button class="btn sm" data-dc="${r.id}">Decline</button>` : ''}</td></tr>`).join('')}</tbody></table></div>`;
    const planCard = r => { const st = r.status; const stepIdx = { requested: 1, quoted: 2, paid: 3, active: 4, declined: 0 }[st]; const steps = ['Requested', 'Quoted', 'Paid', 'Confirmed', 'Active'];
      return `<div class="card"><div class="row gap14 wrap">${RC.av(r.av, 46)}<div class="grow"><b>${r.student}</b> <span class="badge violet">Premium interview plan</span><div class="muted small">Requested ${RC.fmtDate(r.date)}${r.note ? ' · “' + RC.esc(r.note) + '”' : ''}</div></div><span class="badge ${st === 'active' ? 'green' : st === 'declined' ? 'red' : 'amber'}">${st}</span></div>
        <div class="stepper mt12 mb8">${steps.map((s, i) => `<div class="s ${i < stepIdx ? 'done' : i === stepIdx ? 'on' : ''}"><b>${i < stepIdx ? I('check', 13) : i + 1}</b>${s}</div>${i < 4 ? '<div class="ln"></div>' : ''}`).join('')}</div>
        ${st === 'requested' ? `<div class="g2"><div><label class="f">Price to quote (₹) — you decide</label><div class="row gap8"><input class="input" type="number" id="q_${r.id}" value="599"><button class="btn primary" data-quote="${r.id}">Send quote</button></div><div class="hint">Set any price. The student sees it and pays you directly (UPI, bank or office).</div></div><div class="callout info" style="font-size:12.5px">${I('rupee', 16)}<div><b>Cost floor:</b> Premium AI costs Radical about ₹13–37 per full loop (₹21 balanced). Basic ≈ ₹2–4. At ₹599 the AI margin is above 90%.</div></div></div>` : ''}
        ${st === 'quoted' ? `<div class="callout info">${I('clock', 18)}<div>Quote of <b>${RC.inr(r.quote)}</b> sent · reference <b class="mono">${r.code || '—'}</b>. Waiting for the student to pay and submit the payment reference.</div></div><button class="btn sm mt8" data-demopay="${r.id}">Demo: simulate student payment</button>` : ''}
        ${st === 'paid' ? `<div class="g2"><div class="callout warn">${I('card', 18)}<div><b>Payment reference submitted:</b> <span class="mono">${r.ref}</span><br>Quote ${RC.inr(r.quote || 599)}. Check your bank / UPI statement, then confirm.</div></div><div class="col gap8"><label class="row gap8 small"><input type="checkbox" id="ck_${r.id}"> I have verified this payment in Radical’s account</label><div class="row gap8"><button class="btn green grow" data-conf="${r.id}">${I('check', 16)} Confirm &amp; activate Premium</button><button class="btn" data-rej="${r.id}">Reject</button></div></div></div>` : ''}
        ${st === 'active' ? `<div class="callout good">${I('check', 18)}<div>Premium active for 30 days · payment ${r.ref}. Receipt no. <b>RCT/26-27/${RC.rnd(1000, 9999)}</b> generated.</div></div>` : ''}</div>`; };
    return view('requests', 'Requests', 'Credit requests and Premium-plan requests from students', '', `<div class="tabs"><a class="${tab === 'credits' ? 'on' : ''}" href="#/a/requests">Credit requests ${pc ? `<span class="badge red">${pc}</span>` : ''}</a><a class="${tab === 'plans' ? 'on' : ''}" href="#/a/requests?t=plans">Premium plan requests ${pp ? `<span class="badge red">${pp}</span>` : ''}</a></div>${tab === 'credits' ? credits : `<div class="callout info mb16">${I('info', 18)}<div><b>Offline payment flow:</b> student requests → you quote a price → student pays Radical directly (UPI / bank / office) → student submits the reference → you confirm the payment → you activate. No payment gateway; the platform never touches money.</div></div><div class="col gap14">${pl.map(planCard).join('')}</div>`}`, a => {
      RC.$$('[data-ap]', a).forEach(b => b.onclick = () => approveModal(cr.find(r => r.id === b.dataset.ap)));
      RC.$$('[data-dc]', a).forEach(b => b.onclick = () => { const r = cr.find(x => x.id === b.dataset.dc); RC.confirm('Decline this request?', 'The student will be notified. You can add a reason.', 'Decline', () => { r.status = 'declined'; r.note = 'Please use your remaining credits first.'; if (r.mine) notifyStudent('Your credit request was declined: ' + r.note, 'warn'); audit('Declined credit request from ' + r.student); RC.save(); RC.render(); }); });
      RC.$$('[data-quote]', a).forEach(b => b.onclick = () => { const r = pl.find(x => x.id === b.dataset.quote), v = +$('#q_' + r.id, a).value; if (!v) return RC.toast('Enter a price', 'info'); r.quote = v; r.code = nextCode(); r.status = 'quoted'; if (r.student === 'Aarav Sharma') notifyStudent('Radical sent your Premium quote: <b>' + RC.inr(v) + '</b>. Pay and submit the reference to activate.'); audit('Quoted ' + RC.inr(v) + ' for Premium plan to ' + r.student); RC.save(); RC.toast('Quote of ' + RC.inr(v) + ' sent to ' + r.student); RC.render(); });
      RC.$$('[data-demopay]', a).forEach(b => b.onclick = () => { const r = pl.find(x => x.id === b.dataset.demopay); r.status = 'paid'; r.ref = 'UPI 7731 2094 58'; RC.save(); RC.toast('Student submitted payment ref ' + r.ref, 'info'); RC.render(); });
      RC.$$('[data-conf]', a).forEach(b => b.onclick = () => { const r = pl.find(x => x.id === b.dataset.conf); if (!$('#ck_' + r.id, a).checked) return RC.toast('Tick the verification box first', 'info'); r.status = 'active'; if (r.student === 'Aarav Sharma') { S().plan = 'premium'; S().premiumUntil = new Date(2026, 9, 20).toISOString(); RC.ledgerAdd('Premium interview pass activated (30 days)', 0, 'plan'); notifyStudent('Your <b>Premium</b> plan is active until 20 Oct 2026. All 6 rounds are unlocked!'); } audit('Confirmed payment (' + r.ref + ') and activated Premium for ' + r.student); RC.save(); RC.toast('Premium activated for <b>' + r.student + '</b>'); RC.render(); });
      RC.$$('[data-rej]', a).forEach(b => b.onclick = () => { const r = pl.find(x => x.id === b.dataset.rej); r.status = 'declined'; RC.save(); RC.toast('Payment rejected', 'info'); RC.render(); });
    });
  });

  /* ============================================================ COST & USAGE */
  RC.route('/a/costs', 'admin', () => {
    const spend = mtdSpend(), pct = Math.round(spend / D.costs.cap * 100), fc = Math.round(spend / 20 * 30), lean = S().mode === 'lean'; const k = lean ? .62 : 1;
    const rows = [['Profile builder', 5, .094, .094], ['Job match run', 5, .154, .154], ['Tailored ATS resume', 20, 1.363, 1.363], ['Wishlist master resume', 15, .95, .95], ['ATS score check', 5, .086, .086], ['Cover letter', 5, .355, .355], ['Follow-up pack', 5, .055, .055], ['Mock interview (HR) + scorecard', 90, 6.317, 2.534], ['Group discussion + scorecard', 135, 9.36, 4.63], ['Coding round + review', 100, 6.91, 2.18], ['Salary negotiation + scorecard', 60, 4.28, 1.44]];
    const users = D.users.slice(0, 7).map((u, i) => ({ u, v: [212, 188, 165, 141, 128, 97, 86][i] }));
    return view('costs', 'Cost & usage monitor', 'Real ₹ spend by feature, AI model and student — with a cap and a kill-switch', `<span class="badge ${S().killSwitch ? 'red' : 'green'}" style="font-size:12px">${S().killSwitch ? 'Paid AI paused' : 'Paid AI running'}</span>`, `
      <div class="g4"><div class="card kpi"><span class="l">Spend this month</span><span class="v">${RC.inr(spend)}</span><div class="progress mt8 ${pct > 80 ? 'r' : pct > 60 ? 'a' : ''}"><i style="width:${pct}%"></i></div><span class="d muted">${pct}% of ${RC.inr(D.costs.cap)} cap</span></div><div class="card kpi"><span class="l">Forecast to month-end</span><span class="v">${RC.inr(fc)}</span><span class="d ${fc > D.costs.cap ? 'down' : 'up'}">${fc > D.costs.cap ? 'Above cap by ' + RC.inr(fc - D.costs.cap) : 'Within cap'}</span></div><div class="card kpi"><span class="l">Cost per active student</span><span class="v">${RC.inr(spend / 434)}</span><span class="d up">434 active</span></div><div class="card kpi"><span class="l">Cost per full interview loop</span><span class="v">${RC.inr(36.8 * k, 1)}</span><span class="d ${lean ? 'up' : 'muted'}">${lean ? 'Lean mode ≈ ₹13.4 · saving ' + Math.round((1 - .36) * 100) + '%' : 'Quality mode'}</span></div></div>
      <div class="g-main mt16"><div class="col gap18"><div class="card"><div class="card-h"><h3>Daily spend</h3><div class="legend"><span><i style="background:#B3282D"></i>AI</span><span><i style="background:#6DB33F"></i>Free-tier / self-hosted (₹0)</span></div></div>${RC.barChart(days30(), [{ name: 'AI spend', color: '#B3282D', data: D.costs.spend }], { h: 210, fmt: v => '₹' + Math.round(v) })}</div>
        <div class="g2"><div class="card"><h3 class="mb8">By feature</h3>${RC.donut(D.costs.byFeature.map(f => ({ n: f.n, v: f.v, c: f.c, f: RC.inr(f.v / 10190 * spend) })), 120, '', '')}</div><div class="card"><h3 class="mb8">By AI model</h3>${RC.donut(D.costs.byModel.map(f => ({ n: f.n, v: f.v || 400, c: f.c, f: f.f || RC.inr(f.v / 10150 * spend) })), 120, '', '')}</div></div>
        <div class="card pad0"><div class="card-h" style="padding:16px 18px 0"><h3>What each action really costs</h3><span class="muted small">Credit price is fixed; only Radical’s real bill changes with the AI mode</span></div><table class="table"><thead><tr><th>Action</th><th class="right">Credits</th><th class="right">Max ₹</th><th class="right">Real ₹ (Quality)</th><th class="right">Real ₹ (Lean)</th></tr></thead><tbody>${rows.map(r => `<tr><td>${r[0]}</td><td class="right mono">${r[1]}</td><td class="right mono">${RC.inr(r[1] * CR, 2)}</td><td class="right mono">${RC.inr(r[2], 2)}</td><td class="right mono up">${RC.inr(r[3], 2)}</td></tr>`).join('')}</tbody></table></div></div>
      <div class="col gap14"><div class="card"><h4 class="mb8">AI mode</h4><div class="seg" style="margin-bottom:8px"><a id="mQ" class="${!lean ? 'on' : ''}">Quality</a><a id="mL" class="${lean ? 'on' : ''}">Lean</a></div><p class="small muted">${lean ? '<b>Lean:</b> Standard model scores interviews. Cuts a mock interview from ₹6.3 to ₹2.5.' : '<b>Quality:</b> Premium model writes interview scorecards and the final report.'}</p></div>
        <div class="card"><h4 class="mb8">Budget controls</h4><div class="field"><label class="f">Monthly cap (₹)</label><input class="input" value="${D.costs.cap}"></div><div class="row between mb8"><span class="small">Alert at 80%</span><div class="switch on"></div></div><div class="row between mb8"><span class="small">Auto-switch to Lean at 90%</span><div class="switch on"></div></div><div class="row between"><div><b class="small" style="color:var(--red)">Kill-switch (pause paid AI)</b><div class="tiny muted">Students see “AI is resting”</div></div><div class="switch ${S().killSwitch ? 'on' : ''}" id="kill" style="${S().killSwitch ? 'background:var(--red)' : ''}"></div></div></div>
        <div class="card"><h4 class="mb8">Top AI spenders (₹, month)</h4>${users.map(x => `<div class="row gap8 mb8">${RC.av(x.u.av, 28)}<span class="grow small">${x.u.name}</span><b class="mono small">${RC.inr(x.v)}</b></div>`).join('')}</div>
        <div class="card"><h4 class="mb8">Where the compute runs</h4><div class="small mb8"><span class="badge green">Self-hosted</span> embeddings, speech-to-text, code sandbox — ₹0 per use</div><div class="small"><span class="badge red">Paid API</span> writing and scoring, ₹1–₹6 per task</div></div></div></div>`, a => {
      $('#mQ', a).onclick = () => { S().mode = 'quality'; audit('Switched AI mode to Quality'); RC.save(); RC.render(); }; $('#mL', a).onclick = () => { S().mode = 'lean'; audit('Switched AI mode to Lean'); RC.save(); RC.toast('Lean mode on — interview scorecards now use the Standard model', 'info'); RC.render(); };
      $('#kill', a).onclick = () => { const on = !S().killSwitch; RC.confirm(on ? 'Pause all paid AI?' : 'Resume paid AI?', on ? 'Students will see “AI is resting” for paid features. Self-hosted features keep working.' : 'Paid AI features resume immediately.', on ? 'Pause' : 'Resume', () => { S().killSwitch = on; audit((on ? 'Paused' : 'Resumed') + ' paid AI (kill-switch)'); RC.save(); RC.render(); }); };
    });
  });

  /* ============================================================ JOBS & CONTENT */
  RC.route('/a/content', 'admin', () => {
    const q = new URLSearchParams((location.hash.split('?')[1]) || ''); const tab = q.get('t') || 'sources'; S().blocked = S().blocked || ['Acme Staffing', 'QuickHire Consultants'];
    const tabs = [['sources', 'Job sources'], ['banks', 'Question banks'], ['courses', 'Course catalogue'], ['blocked', 'Blocked companies']];
    const body = {
      sources: `<div class="callout info mb16">${I('shield', 18)}<div>Jobs come from <b>company career pages, licensed job APIs and Radical’s hiring partners</b>. LinkedIn and Naukri are opened by deep link — never scraped — to respect their terms.</div></div><div class="card pad0"><table class="table"><thead><tr><th>Source</th><th>What it covers</th><th class="right">Live jobs</th><th>Last crawl</th><th>Status</th><th></th></tr></thead><tbody>${D.sources.map((s, i) => `<tr><td><b>${s.n}</b></td><td class="small muted">${s.d}</td><td class="right mono">${RC.num(s.jobs)}</td><td class="small">${s.last}</td><td><span class="badge ${s.st === 'ok' ? 'green' : s.st === 'warn' ? 'amber' : 'steel'}">${s.st === 'ok' ? 'Healthy' : s.st === 'warn' ? 'Slow' : 'Links only'}</span></td><td class="right">${s.st !== 'link' ? `<button class="btn sm" data-run="${i}">${I('refresh', 14)} Run now</button>` : ''}</td></tr>`).join('')}</tbody></table></div>`,
      banks: `<div class="g3">${D.banks.map(b => `<div class="card"><div class="row between"><h3>${b.n}</h3><span class="badge green">${b.r}</span></div><div style="font:700 32px var(--f-head)" class="mt8">${RC.num(b.v)}</div><div class="muted small">${b.d}</div><div class="row gap8 mt12"><button class="btn sm grow" data-add="${b.n}">${I('plus', 14)} Add</button><button class="btn sm grow">Import CSV</button></div></div>`).join('')}</div><div class="callout info mt16">${I('info', 18)}<div>Aptitude and technical questions are <b>never generated on the fly</b> — trainers review every question and its answer key, so students always see correct answers.</div></div>`,
      courses: `<div class="card pad0"><table class="table"><thead><tr><th>Course</th><th>Category</th><th>Hours</th><th>Next batch</th><th>Skills mapped (used for recommendations)</th><th>Show</th></tr></thead><tbody>${D.courses.map(c => `<tr><td><b>${c.title}</b></td><td>${c.cat}</td><td>${c.hrs}</td><td>${c.next}</td><td>${c.skills.map(s => `<span class="badge steel">${s}</span>`).join(' ')}</td><td><div class="switch on"></div></td></tr>`).join('')}</tbody></table></div>`,
      blocked: `<div class="card"><div class="row gap8 mb16"><input class="input" id="bIn" placeholder="Company name to block" style="max-width:320px"><button class="btn primary" id="bAdd">Block company</button></div>${S().blocked.map((b, i) => `<div class="row between card flat tight mb8"><b>${b}</b><button class="btn sm" data-ub="${i}">Unblock</button></div>`).join('')}<p class="small muted mt8">Jobs from blocked companies are removed from every student’s feed at the next crawl.</p></div>`
    };
    return view('content', 'Jobs & content', 'Job sources, question banks, course catalogue and blocked companies', '', `<div class="card"><div class="tabs">${tabs.map(t => `<a class="${t[0] === tab ? 'on' : ''}" href="#/a/content?t=${t[0]}">${t[1]}</a>`).join('')}</div>${body[tab]}</div>`, a => {
      RC.$$('[data-run]', a).forEach(b => b.onclick = async () => { b.innerHTML = '<span class="spin"></span>'; await RC.sleep(1600); b.innerHTML = I('check', 14) + ' Done'; audit('Ran crawl for ' + D.sources[+b.dataset.run].n); RC.toast('Crawl finished: <b>+186 new</b>, 41 expired, 12 duplicates removed'); });
      RC.$$('[data-add]', a).forEach(b => b.onclick = () => RC.modal({ title: 'Add to ' + b.dataset.add, body: `<div class="field"><label class="f">Question</label><textarea class="input">Which AWS service is used for DNS routing?</textarea></div><div class="g2"><div class="field"><label class="f">Correct answer</label><input class="input" value="Amazon Route 53"></div><div class="field"><label class="f">Topic</label><input class="input" value="AWS"></div></div>`, footer: `<button class="btn" data-close>Cancel</button><button class="btn primary" id="ok">Save for review</button>`, mount: m => $('#ok', m).onclick = () => { RC.closeModal(); RC.toast('Saved — a second trainer will review it before it goes live', 'info'); } }));
      const ba = $('#bAdd', a); if (ba) ba.onclick = () => { const v = $('#bIn', a).value.trim(); if (!v) return; S().blocked.push(v); audit('Blocked company ' + v); RC.save(); RC.render(); }; RC.$$('[data-ub]', a).forEach(b => b.onclick = () => { S().blocked.splice(+b.dataset.ub, 1); RC.save(); RC.render(); });
    });
  });

  /* ============================================================ SESSIONS */
  RC.route('/a/sessions', 'admin', () => view('sessions', 'Interview sessions', 'Every AI interview with its score, transcript and feedback — for counsellors and trainers', `<button class="btn">${I('download', 16)} Export</button>`, `<div class="g4 mb16"><div class="card kpi"><span class="l">Sessions this month</span><span class="v">1,486</span></div><div class="card kpi"><span class="l">Avg. score</span><span class="v">66</span></div><div class="card kpi"><span class="l">Premium share</span><span class="v">14%</span></div><div class="card kpi"><span class="l">Weakest round</span><span class="v" style="font-size:20px">Coding</span></div></div>
    <div class="card pad0"><table class="table"><thead><tr><th>Student</th><th>Round</th><th>Plan</th><th>Score</th><th>Duration</th><th>Date</th><th></th></tr></thead><tbody>${D.sessions.map((s, i) => `<tr class="click" data-s="${i}"><td><div class="row gap8">${RC.av(s.av, 32)}<b>${s.s}</b></div></td><td>${s.r}</td><td><span class="badge ${s.p === 'Premium' ? 'violet' : ''}">${s.p}</span></td><td><span class="badge ${RC.scoreColor(s.sc)}">${s.sc}/100</span></td><td class="small">${s.t}</td><td class="small muted">${s.d}</td><td class="right">${I('chevR', 16)}</td></tr>`).join('')}</tbody></table></div>`, a => {
    RC.$$('[data-s]', a).forEach(r => r.onclick = () => { const s = D.sessions[+r.dataset.s]; RC.drawer(`<div class="row gap14 mb16">${RC.av(s.av, 56)}<div><h2>${s.s}</h2><div class="muted">${s.r} · ${s.d}</div></div></div><div class="row gap14 mb16">${RC.ring(s.sc, 90, 10, null, s.sc, '/100')}<div class="grow">${[['Content', s.sc + 4], ['Communication', s.sc - 8], ['Structure', s.sc + 2], ['Confidence', s.sc - 3]].map(x => `<div class="skillbar" style="grid-template-columns:100px 1fr 34px;margin:4px 0"><span class="small">${x[0]}</span><div class="progress thin ${x[1] >= 70 ? 'g' : 'a'}"><i style="width:${x[1]}%"></i></div><b class="mono small">${Math.min(99, x[1])}</b></div>`).join('')}</div></div><h4 class="mb8">Transcript excerpt</h4><div class="col gap8"><div class="tmsg">${RC.av('priya', 28)}<div class="b">Tell me about a challenge you faced in a project.</div></div><div class="tmsg you">${RC.av(s.av, 28)}<div class="b">Umm, once my deployment failed and I, like, searched on Google and it worked after some time.</div></div></div><div class="fb-issue mt12"><b>AI note:</b> vague STAR structure and 3 fillers. Suggested course: Interview &amp; Career Skills Bootcamp.</div><div class="row gap8 mt16"><button class="btn primary grow" id="cn">${I('mail', 14)} Contact student</button></div>`); });
  }));

  /* ============================================================ REPORTS */
  RC.route('/a/reports', 'admin', () => {
    const leads = (S().leadsNew || []).concat(D.leads);
    return view('reports', 'Reports & insights', 'Placement funnel, skill gaps and course leads — decisions for Radical’s batches', `<button class="btn" id="exp">${I('download', 16)} Export (Excel)</button>`, `
      <div class="g4"><div class="card kpi"><span class="l">Applications sent</span><span class="v">3,842</span><span class="d up">▲ 18% vs last month</span></div><div class="card kpi"><span class="l">Interviews secured (self-reported)</span><span class="v">412</span><span class="d up">10.7% of applications</span></div><div class="card kpi"><span class="l">Offers reported</span><span class="v">73</span><span class="d up">▲ 21 this month</span></div><div class="card kpi"><span class="l">Course enquiries from AI</span><span class="v">${96 + (S().leadsNew || []).length}</span><span class="d up">from skill-gap recommendations</span></div></div>
      <div class="g2 mt16"><div class="card"><div class="card-h"><h3>Placement funnel</h3></div>${D.funnel.map((f, i) => `<div class="row gap8 mb12"><span class="small" style="width:170px">${f[0]}</span><div class="progress grow" style="height:14px"><i style="width:${f[1] / 12.4}%;${i >= 5 ? 'background:var(--violet)' : ''}"></i></div><b class="mono small" style="width:52px;text-align:right">${RC.num(f[1])}</b></div>`).join('')}</div>
      <div class="card"><div class="card-h"><h3>Average mock-interview score by batch</h3></div>${RC.barChart(['AWS', 'Azure', 'Python', 'Cyber', 'Public'], [{ name: 'Aptitude', color: '#3F5A86', data: [68, 62, 71, 58, 55] }, { name: 'Technical', color: '#0B7E62', data: [72, 66, 69, 61, 52] }, { name: 'Communication', color: '#B3282D', data: [58, 60, 55, 57, 49] }], { h: 210, max: 100 })}</div></div>
      <div class="g2 mt16"><div class="card"><div class="card-h"><h3>Top skill gaps (students scoring below 50)</h3><span class="muted small">Plan your next batches around these</span></div>${D.gaps.map(g => `<div class="row gap8 mb12"><span class="small" style="width:160px">${g[0]}</span><div class="progress r grow"><i style="width:${g[1] * 2}%"></i></div><b class="mono small">${g[1]}%</b></div>`).join('')}<div class="callout warn mt8" style="font-size:12.5px">${I('spark', 16)}<div><b>Insight:</b> Kubernetes and communication gaps are the two biggest — a joint “DevOps + Interview Skills” combo batch would address 60% of students.</div></div></div>
      <div class="card"><div class="card-h"><h3>${I('users', 16)} Course leads from AI recommendations</h3><span class="badge red">${leads.filter(l => l.st === 'New').length} new</span></div><div class="col gap8">${leads.slice(0, 6).map(l => `<div class="row gap8 card flat tight"><div class="grow"><b class="small">${l.n}</b> <span class="muted small">→ ${l.c}</span><div class="tiny muted">${l.why} · ${l.t}</div></div><span class="badge ${l.st === 'New' ? 'red' : l.st === 'Enrolled' ? 'green' : 'amber'}">${l.st}</span></div>`).join('')}</div></div></div>`, a => { $('#exp', a).onclick = () => RC.toast('Exported <b>careerai-report-sep-2026.xlsx</b> (demo)', 'info'); });
  });

  /* ============================================================ SETTINGS & AUDIT */
  RC.route('/a/settings', 'admin', () => {
    const q = new URLSearchParams((location.hash.split('?')[1]) || ''); const tab = q.get('t') || 'audit';
    const tabs = [['audit', 'Audit log'], ['team', 'Team & roles'], ['privacy', 'Privacy & DPDP'], ['general', 'General']];
    const all = (S().auditLive || []).concat(D.audit);
    const body = {
      audit: `<div class="timeline">${all.map(a => `<div class="ev"><div>${a[1]}</div><div class="tiny muted">${a[0]} · ${a[2]}</div></div>`).join('')}</div>`,
      team: `<table class="table"><thead><tr><th>Member</th><th>Role</th><th>2-step login</th><th></th></tr></thead><tbody>${[['Sneha Kulkarni', 'Super admin', 'sneha'], ['Ravi Nair', 'Placement admin', 'u5'], ['Meenal Joshi', 'Counsellor (read-only)', 'u1'], ['Trainer — Amit Bhosale', 'Content reviewer', 'u8']].map(m => `<tr><td><div class="row gap8">${RC.av(m[2], 32)}<b>${m[0]}</b></div></td><td><span class="badge ${m[1] === 'Super admin' ? 'red' : ''}">${m[1]}</span></td><td><span class="badge green">Enabled</span></td><td class="right"><button class="btn sm">Edit</button></td></tr>`).join('')}</tbody></table>`,
      privacy: `<div class="g2"><div class="card flat"><h4 class="mb8">Consent records</h4><div class="kv"><dt>Resume processing</dt><dd>1,240 / 1,240</dd><dt>History retention</dt><dd>1,118 opted in</dd><dt>Share with placement team</dt><dd>642 opted in</dd></div></div><div class="card flat"><h4 class="mb8">Data requests (DPDP)</h4><div class="row between mb8"><span>Download my data</span><span class="badge green">14 fulfilled</span></div><div class="row between mb8"><span>Delete my account</span><span class="badge amber">2 pending</span></div><button class="btn sm">Review deletions</button></div></div><div class="callout info mt16">${I('shield', 18)}<div>Personal identifiers are removed before text is sent to any paid AI provider. Servers are hosted in India. Nightly backups are encrypted.</div></div>`,
      general: `<div class="g2"><div class="field"><label class="f">Organisation</label><input class="input" value="Radical Technologies"></div><div class="field"><label class="f">Support email</label><input class="input" value="training@radicaltechnologies.co.in"></div><div class="field"><label class="f">Public sign-up</label><select class="input"><option>Open to everyone</option><option>Invite only</option></select></div><div class="field"><label class="f">Email verification</label><select class="input"><option>Required before credits</option></select></div></div><button class="btn primary" id="sv">Save</button>`
    };
    return view('settings', 'Settings & audit', 'Team, privacy, and a permanent record of every admin action', '', `<div class="card"><div class="tabs">${tabs.map(t => `<a class="${t[0] === tab ? 'on' : ''}" href="#/a/settings?t=${t[0]}">${t[1]}</a>`).join('')}</div>${body[tab]}</div>`, a => { const s = $('#sv', a); if (s) s.onclick = () => RC.toast('Settings saved'); });
  });
})();
